      {title:"A new camera-account device appears",situation:"The CCTV app shows a new sign-in device you cannot identify.",question:"What is a safe first response?",choices:[["Post the camera password to ask the internet",false,"Keep the account credential private."],["Secure the account through the official app and review users and sessions",true,"Remove access you cannot verify and contact the vendor if needed."],["Try to access another camera to compare",false,"Only manage equipment you own or are authorized to administer."]]}
      ,{title:"A new camera needs remote access",situation:"An installer asks you to open router settings for remote viewing but does not explain the method.",question:"What should you do?",choices:[["Enable every remote-access option",false,"Unnecessary exposure can add risk and may be hard to undo."],["Ask the installer to explain the exact setting and verify it in official documentation",true,"Understand the access path and who can view the system before approving it."],["Share your router admin login by text",false,"Do not share administrator credentials casually."]]}
