      {title:"A sign-in approval you did not start",situation:"Your phone asks you to approve a login you did not attempt.",question:"What is the safest response?",choices:[["Approve it to stop the notification",false,"That may let someone else into your account."],["Deny it, then check the account from its official app or website",true,"Review activity and secure the account if there are unfamiliar sessions."],["Send the approval number to the caller",false,"Keep codes and prompts private."]]}
      ,{title:"A shared computer remembers your account",situation:"You used a library computer and are not sure whether you signed out of email.",question:"What can you do from your own trusted device?",choices:[["Change every account from that public computer",false,"Use your own trusted device for account security."],["Review sessions and sign out the shared session through official account settings",true,"This can end access without returning to the computer."],["Save your password in the public browser",false,"That leaves credentials available to the next user."]]}
      ,{title:"An unfamiliar recovery email was added",situation:"An account security page shows a recovery address you do not recognize.",question:"What should you do?",choices:[["Ignore it because you can still log in",false,"An unknown recovery route may affect future access."],["Secure the account, remove it through official settings, and check sessions",true,"Review both recovery methods and active access."],["Send a reset code to the unknown address",false,"That would give it more access."]]}
